// 按全国组委会正式通知更正报名开放日和直达入口；默认预览。
import fs from 'node:fs/promises';import path from 'node:path';import {fileURLToPath} from 'node:url';
const here=path.dirname(fileURLToPath(import.meta.url));const token=(await fs.readFile(path.join(here,'.admin-token'),'utf8')).trim();
const id='edition-cmp028-2026',notice='https://ucc.fltrp.com/c/2026-04-15/517928.shtml',entry='https://stu-ucc.fltrp.com/uchallenge/signUp.html';
async function call(action,data={}){const r=await fetch('http://127.0.0.1:8787/api/adminData',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({adminToken:token,action,...data})});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.message||`HTTP ${r.status}`);return j.data}
const state=await call('bootstrap');const m=state.records.filter(x=>x.id===id);if(m.length!==1)throw new Error('target_not_unique');const old=m[0];if(old.dataStatus!=='pending_manual_review'||old.registrationUrl!=='https://ucc.fltrp.com/'||old.schedule?.registration_start!=='2026-06-03T00:00:00+00:00')throw new Error('target_changed');
const r=await fetch(notice,{redirect:'follow',signal:AbortSignal.timeout(15000)});const h=await r.text();if(r.status!==200||r.url!==notice||!h.includes('6月2日')||!h.includes('开放参赛报名页面'))throw new Error('notice_unverified');const e=await fetch(entry,{redirect:'follow',signal:AbortSignal.timeout(15000)});if(e.status!==200||e.url!==entry)throw new Error('entry_unverified');
console.log(JSON.stringify({version:state.stateVersions.records,id,oldStart:old.schedule.registration_start,newStart:'2026-06-02',oldEntry:old.registrationUrl,newEntry:entry,notice,finalUrl:r.url}));
if(!process.argv.includes('--apply'))process.exit(0);if(process.argv[process.argv.indexOf('--expect-version')+1]!==String(state.stateVersions.records))throw new Error('preview_changed');
const backupDir=path.join(here,'backups',`national-language-start-${new Date().toISOString().replace(/[:.]/g,'-')}`);await fs.mkdir(backupDir,{recursive:true,mode:0o700});await fs.writeFile(path.join(backupDir,'records-before.json'),JSON.stringify(state,null,2),{mode:0o600});const now=new Date().toISOString();
const changed={...old,registrationUrl:entry,lastVerifiedAt:now,updatedAt:now,updatedBy:'manual-official-source-correction',
  schedule:{...old.schedule,registration_start:'2026-06-02',time_note:'全国组委会通知明确官网2026年6月2日起开放报名；各校和赛项的截止日不同，须按学校及省赛通知核对。'},
  qualityIssues:['各校及赛项报名截止日期不同，不能填写统一截止日','须核对所在学校的校赛报名及晋级安排'],
  sources:[...old.sources,{id:'source-cmp028-2026-official-notice',edition_id:id,url:notice,source_type:'organizer_website',is_official:true,validity_status:'valid',published_at:'2026-04-16',last_verified_at:now,final_url:notice,evidence_excerpt:'北京外国语大学正式通知：大赛官网于2026年6月2日起开放参赛报名页面，各校报名截止时间自行规定。'}],aiReview:null};
const current=await call('bootstrap');if(current.stateVersions.records!==state.stateVersions.records||JSON.stringify(current.records.find(x=>x.id===id))!==JSON.stringify(old))throw new Error('concurrent_change');
await call('saveRecords',{records:current.records.map(x=>x.id===id?changed:x),expectedVersion:current.stateVersions.records,auditEntry:{id:`correct-national-language-start-${Date.now()}`,action:'update',objectType:'event_edition',recordId:id,recordName:old.name,changedFields:['schedule.registration_start','registrationUrl','sources','qualityIssues'],actor:'super_admin',reason:`组委会正式通知将报名开放日确定为6月2日，不是6月3日报名指南发布日期；备份：${backupDir}`,createdAt:now}});
const after=await call('bootstrap');const saved=after.records.find(x=>x.id===id);if(saved?.schedule.registration_start!=='2026-06-02'||saved.registrationUrl!==entry)throw new Error('write_verification_failed');console.log(JSON.stringify({updated:id,status:saved.dataStatus,backupDir,verified:true}));
